/// <summary>
/// Developer-only form to seed HR Order Type Groups and Order Types.
/// Not added to navigation menus; intended to be opened via URL using a Menu Item.
/// </summary>
[Form]
public class NVOrderTypeSeedForm extends FormRun
{
}

/// <summary>
/// Initializes the form.
/// </summary>
public void init()
{
    super();

    // Optional: add any extra runtime checks here if needed.
    // Example: show current company context to avoid surprises in per-company tables.
}

private int getGroupsCount()
{
    // Note: count(RecId) returns in the RecId field of the aggregate buffer.
    return (select count(RecId) from NVOrderTypeGroup).RecId;
}

private int getTypesCount()
{
    return (select count(RecId) from NVOrderTypeTable).RecId;
}

private boolean confirmRun(str _title, str _message, DialogButton _defaultButton = DialogButton::No)
{
    return Box::yesNo(_message, _defaultButton, _title) == DialogButton::Yes;
}

private void runFillGroups()
{
    int existingCount = this.getGroupsCount();

    // Soft warning (do not hard block): let dev decide.
    if (existingCount >= 12)
    {
        if (!this.confirmRun(
                "Data already exists",
                strFmt("Table NVOrderTypeGroup already contains %1 records.\n\nDo you want to run the job anyway?", existingCount),
                DialogButton::No))
        {
            return;
        }
    }

    if (!this.confirmRun(
            "Confirm seed (Groups)",
            strFmt("This will seed Order Type Groups.\n\nCompany: %1\n\nContinue?", curext()),
            DialogButton::No))
    {
        return;
    }

    try
    {
        setPrefix("Seed Order Type Groups");

        // Run the job class (developer tool)
        NVFillOrderTypeGroups::main(null);

        Box::info("Order Type Groups seed job finished. Check Infolog for details.", "Done");
    }
    catch (Exception::Error)
    {
        error("Order Type Groups seed job failed. Check Infolog for details.");
    }
}

private void runFillTypes()
{
    int groupsCount   = this.getGroupsCount();
    int existingTypes = this.getTypesCount();

    // Prerequisite check
    if (groupsCount == 0)
    {
        Box::warning(
            "NVOrderTypeGroup is empty.\n\nRun 'Fill Groups' first, then run 'Fill Types'.",
            "Missing prerequisite");
        return;
    }

    if (existingTypes >= 62)
    {
        if (!this.confirmRun(
                "Data already exists",
                strFmt("Table NVOrderTypeTable already contains %1 records.\n\nDo you want to run the job anyway?", existingTypes),
                DialogButton::No))
        {
            return;
        }
    }

    if (!this.confirmRun(
            "Confirm seed (Types)",
            strFmt("This will seed Order Types.\n\nCompany: %1\n\nContinue?", curext()),
            DialogButton::No))
    {
        return;
    }

    try
    {
        setPrefix("Seed Order Types");

        // Run the job class (developer tool)
        NVFillOrderTypes::main(null);

        Box::info("Order Types seed job finished. Check Infolog for details.", "Done");
    }
    catch (Exception::Error)
    {
        error("Order Types seed job failed. Check Infolog for details.");
    }
}
